// Parse e-commerce order data
// Supports: Shopee, Tokopedia, Lazada, etc.
const data = $input.first().json;

// Normalize data structure
const order = {
  external_order_id: data.order_id || data.orderNo,
  platform: data.platform || data.source || 'ecommerce',
  customer_name: data.customer_name || data.buyer_name,
  customer_phone: data.customer_phone || data.recipient_phone,
  customer_address: data.customer_address || data.recipient_address,
  items: data.items || data.products || [{
    sku: data.sku,
    name: data.product_name,
    qty: data.qty || data.quantity,
    price: data.price || data.unit_price
  }],
  total_amount: data.total_amount || data.total,
  shipping_cost: data.shipping_cost || 0,
  order_date: data.order_date || new Date().toISOString()
};

return [{ json: order }];

